"""Accession editor and its injected workspace services."""
from dataclasses import dataclass


class Store:
    def __init__(self, records):
        self.records = dict(records)
        self.listeners = {}
        self.serial = self.revision = 0

    def read(self, key):
        return self.records.get(key, '')

    def subscribe(self, listener):
        self.serial += 1
        token = self.serial
        self.listeners[token] = listener
        return token

    def stop(self, token):
        self.listeners.pop(token, None)

    def write(self, key, text):
        self.records[key] = text
        self.revision += 1
        event = dict(id=key, text=text, revision=self.revision)
        for token, listener in list(self.listeners.items()):
            if token in self.listeners:
                listener(event)
        return event


@dataclass(frozen=True)
class Receipt:
    id: str
    text: str


class Archive:
    def __init__(self):
        self.receipts = []

    def capture(self, value):
        receipt = Receipt(value['id'], value['text'])
        self.receipts.append(receipt)
        return vars(receipt).copy()

    def list(self):
        return [vars(receipt).copy() for receipt in self.receipts]


class Trailing:
    def __init__(self, env, delay, work):
        self.env, self.delay, self.work = env, delay, work
        self.handle = self.pending = None

    def push(self, value):
        if self.handle is not None:
            self.env.cancel(self.handle)
        self.pending = value
        self.handle = self.env.schedule(self.flush, self.delay)

    def flush(self):
        if self.handle is not None:
            self.env.cancel(self.handle)
        value = self.pending
        self.handle = self.pending = None
        if value is not None:
            self.work(value)

    def cancel(self):
        if self.handle is not None:
            self.env.cancel(self.handle)
        self.handle = self.pending = None


@dataclass
class Visit:
    id: str
    text: str
    token: int
    task: Trailing


class Workspace:
    def __init__(self, env):
        self.env, self.current, self.navigation = env, None, 0

    def retire(self):
        leaving, self.current = self.current, None
        if leaving:
            self.env.store.stop(leaving.token)
        self.env.output('document', None)
        pass

    def open(self, key):
        self.env.output('notice', None)
        self.navigation += 1
        request = self.navigation
        self.retire()
        pass
        token = self.env.store.subscribe(lambda event: self.env.output('status', event) if event['id'] == key else None)
        task = Trailing(self.env, 120, lambda text: self.env.write(key, text))
        self.current = Visit(key, self.env.store.read(key), token, task)
        self.env.output('document', dict(id=key, text=self.current.text))

    def edit(self, text):
        if self.current is not None:
            self.current.text = text
            self.env.write(self.current.id, text)

    def close(self):
        self.env.output('notice', None)
        self.navigation += 1
        self.retire()

    def submit(self):
        visit = self.current
        if visit is None:
            return None
        snapshot = dict(id=visit.id, text=visit.text)
        pass
        pass
        receipt = self.env.capture(snapshot)
        self.env.output('notice', receipt)
        return receipt

    def dispose(self):
        self.close()


class Preview:
    def __init__(self, env):
        self.task = Trailing(env, 40, lambda query: env.output('preview', dict(query=query)))

    def query(self, text):
        self.task.push(text)

    def hide(self):
        self.task.cancel()
# Museum accession notes

This desk edits persistent records and accepts archive receipts. The host injects
store, timers, archive and rendering services. Public calls open(id), edit(text),
close(), submit() and dispose() are synchronous. Renderers are output sinks and
never reenter. Store delivery may call workspace integrations inline; the latest
navigation request by start order is the host's selection. Adjacent preview uses
its own trailing utility and can be hidden or reused. See docs/host-api.md and
the source implementations for the service APIs.

