from src.workflow import Archive, Store, Workspace

class Env:
    def __init__(self):
        self.store = Store({'a': 'old', 'b': 'bee'})
        self.events = []
        self.jobs = {}
        self.next_handle = 0
        self.archive = Archive()
    def schedule(self, callback, delay):
        self.next_handle += 1
        self.jobs[self.next_handle] = (callback, delay)
        return self.next_handle
    def cancel(self, handle):
        self.jobs.pop(handle, None)
    def run_all(self):
        while self.jobs:
            handle = next(iter(self.jobs))
            callback, _ = self.jobs.pop(handle)
            callback()
    def write(self, key, text):
        return self.store.write(key, text)
    def capture(self, value):
        assert self.store.read(value['id']) == value['text']
        return self.archive.capture(value)
    def output(self, kind, value):
        self.events.append((kind, value))

env = Env(); desk = Workspace(env)
desk.open('a')
desk.edit('one'); desk.edit('two'); desk.edit('three')
assert env.store.revision == 0
env.run_all()
assert env.store.read('a') == 'three' and env.store.revision == 1
desk.edit('four'); desk.close()
assert env.store.read('a') == 'four' and not env.jobs
desk.open('a'); desk.edit('five')
receipt = desk.submit()
assert receipt == {'id': 'a', 'text': 'five'}
assert env.store.read('a') == 'five' and not env.jobs
desk.edit('six'); env.run_all()
assert env.store.read('a') == 'six' and env.store.revision == 4
print('workflow behavior checks passed')
PY"

